-- Follow the Neovim configuration generated by the active Omarchy theme.
local theme_file = vim.fn.expand("~/.local/state/omarchy/current/theme/neovim.lua")
if vim.fn.filereadable(theme_file) == 0 then
  theme_file = vim.fn.expand("~/.config/omarchy/current/theme/neovim.lua")
end

if vim.fn.filereadable(theme_file) == 1 then
  local spec = dofile(theme_file)
  for _, plugin in ipairs(spec) do
    -- Reuse the installed plugin and the matching all-themes.lua entry.
    if plugin[1] and plugin[1]:match("/aether%.nvim$") then
      plugin.name = "aether.nvim"
    end
  end
  return spec
end

return {
  { "LazyVim/LazyVim", opts = { colorscheme = "tokyonight" } },
}
